param([string]$MsiPath,[string]$ExpectedPublisher)
$ErrorActionPreference='Stop'; $root='Registry::HKEY_LOCAL_MACHINE\SOFTWARE\Shale\Installations'; Write-Output "registrationLocation=HKLM\SOFTWARE\Shale\Installations"; if (-not (Test-Path $root)) { Write-Output 'classification=UNAVAILABLE'; exit 2 }; $seen=@{}; foreach ($key in Get-ChildItem $root) { $r=Get-ItemProperty $key.PSPath; $classification='VALID'; if ($r.schemaVersion -ne 1) { $classification='INVALID_SCHEMA' } elseif ($r.ownerSid -notmatch '^S-1-(?:\d+-){1,14}\d+$') { $classification='INVALID_OWNER' } elseif (-not (Test-Path -LiteralPath $r.installRoot)) { $classification='STALE' } elseif (@(Get-Item -LiteralPath $r.installRoot,$r.supportRoot -Force | Where-Object { ($_.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0 }).Count -ne 0) { $classification='REPARSE_UNSAFE' }; if ($seen.ContainsKey($r.installationId)) { $classification='DUPLICATE_INSTALLATION_ID' }; $seen[$r.installationId]=$true; $updater=Join-Path $r.installRoot 'app\updater\ShaleUpdater.exe'; $version=Join-Path $r.installRoot 'app\shale-installed-version.properties'; $attempt=Join-Path $r.supportRoot 'update-attempts'; $lock=Join-Path $r.supportRoot 'updates\update-execution.lock'; $logs=Join-Path $r.supportRoot 'logs\updates'; Write-Output "classification=$classification schemaVersion=$($r.schemaVersion) installationId=$($r.installationId) ownerSid=$($r.ownerSid)"; Write-Output "installRoot=$($r.installRoot) supportRoot=$($r.supportRoot)"; Write-Output "updater=$updater versionMetadata=$version attemptStore=$attempt executionLock=$lock evidenceLogs=$logs"; Write-Output "acl=$((Get-Acl $key.PSPath).Sddl)"; if (Test-Path $version) { Get-Content $version | ForEach-Object { Write-Output "installedVersion.$_" } }; foreach ($artifact in @((Join-Path $r.installRoot 'Shale.exe'),$updater)) { $signature=Get-AuthenticodeSignature $artifact; Write-Output "authenticode.path=$artifact status=$($signature.Status) publisher=$($signature.SignerCertificate.Subject) timestamp=$($signature.TimeStamperCertificate.Subject)" } }; if ($MsiPath) { $signature=Get-AuthenticodeSignature $MsiPath; Write-Output "authenticode.path=$MsiPath status=$($signature.Status) publisher=$($signature.SignerCertificate.Subject) timestamp=$($signature.TimeStamperCertificate.Subject)"; if ($ExpectedPublisher -and ($signature.Status -ne 'Valid' -or $signature.SignerCertificate.Subject -notlike "*$ExpectedPublisher*")) { exit 3 } }
